// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 initial, uint256 amount) public {
        initial = bound(initial, 1 ether, 1000 ether);
        amount = bound(amount, 1, initial - 1);
        vm.deal(address(c), initial);
        uint256 balBefore = address(c).balance;
        vm.prank(address(this));
        try c.sendTo(address(0xBEEF), amount) {
            assertEq(address(c).balance, balBefore - amount,
                "successful sendTo must decrease contract balance by exactly amount");
        } catch {
            assertEq(address(c).balance, balBefore);
        }
    }
}
